const targets = await (await fetch('http://127.0.0.1:9222/json')).json();
const target = targets.find((t) => t.type === 'page');
if (!target) throw new Error('No Chrome page target');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let nextId = 0;
const pending = new Map();
ws.onmessage = ({ data }) => {
  const msg = JSON.parse(data);
  if (msg.id && pending.has(msg.id)) { pending.get(msg.id)(msg); pending.delete(msg.id); }
};
function send(method, params = {}) {
  return new Promise((resolve) => { const id = ++nextId; pending.set(id, resolve); ws.send(JSON.stringify({ id, method, params })); });
}
async function evalJS(expression) {
  const r = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (r.result.exceptionDetails) throw new Error(r.result.exceptionDetails.text);
  return r.result.result.value;
}
await send('Page.enable');
await send('Runtime.enable');
await send('Page.navigate', { url: 'http://127.0.0.1:8765/index.html' });
for (let i=0; i<80; i++) {
  try { const ready = await evalJS("document.readyState === 'complete' && !!document.querySelector('#begin')"); if (ready) break; } catch {}
  await new Promise(r=>setTimeout(r,200));
}
await evalJS("document.querySelector('#begin').click()");
const initial = await evalJS("({title:document.querySelector('#storyTitle').textContent, progress:document.querySelector('#storyProgress').textContent, tag:document.querySelector('#sceneTag').textContent, caption:document.querySelector('#sceneCaption').textContent, villain:document.querySelector('#storyScene').dataset.villain})");
const beats=[];
for(let i=0;i<40;i++){
  beats.push(await evalJS("({title:document.querySelector('#storyTitle').textContent, progress:document.querySelector('#storyProgress').textContent, tag:document.querySelector('#sceneTag').textContent, caption:document.querySelector('#sceneCaption').textContent, villain:document.querySelector('#storyScene').dataset.villain, bg:getComputedStyle(document.querySelector('#storyScene')).backgroundImage})"));
  if(i<39) await evalJS("document.querySelector('#storyNext').click()");
}
console.log(JSON.stringify({initial, count:beats.length, villains:[...new Set(beats.map(x=>x.villain))], final:beats.at(-1), beats:beats.map(({progress,title,villain})=>({progress,title,villain}))},null,2));
ws.close();

